/* Adapted from EDUCADE public/teacher.js and public/teacher-data.js at
   1a49552d1d76d4d3d9f973369454331b0fe7ba7c, with the owner's permission.
   Reuses its class comparison, learning tabs, accuracy summaries, progress bars
   and radar geometry. Demo records and inferred achievement levels are excluded. */
import {escape} from './workspace-shared.js';
import {learnerEvidence} from './assessment-model.mjs';
export const learningTabs={overall:{name:'Overall'},foundations:{name:'Reading Foundations',domain:'reading',section:'foundations'},literacy:{name:'Literacy',domain:'reading',section:'comprehension'},writing:{name:'Writing',domain:'writing'},grammar:{name:'Grammar',domain:'grammar'},vocabulary:{name:'Vocabulary',domain:'vocabulary'}};
export function summarizePractice(evidence){
 const attempts=evidence.length,correct=evidence.filter(record=>record.correct===true).length;
 return {attempts,correct,score:attempts?Math.round(correct/attempts*100):null,independent:evidence.filter(r=>!r.supported).length,supported:evidence.filter(r=>r.supported).length,hints:evidence.filter(r=>r.hint).length};
}
export function classAxes(catalogue,scope){
 if(scope==='overall')return Object.entries(catalogue.domains).map(([domain,info])=>({id:domain,domain,label:info.name}));
 const tab=learningTabs[scope];
 if(scope==='foundations')return catalogue.groups.filter(g=>g.section==='foundations').flatMap(g=>g.skills.map(s=>({id:s.id,label:s.name})));
 return catalogue.profileAxes[tab.domain];
}
export function axisStats(catalogue,records,axis){
 if(axis.domain){const ids=new Set(catalogue.groups.filter(g=>g.domain===axis.domain).flatMap(g=>g.skills.map(s=>s.id)));return summarizePractice(records.filter(r=>ids.has(r.skillId)));}
 return summarizePractice(records.filter(r=>r.skillId===axis.id));
}
export const progressBar=(score,label)=>score===null?'<span class="educade-no-evidence">No evidence yet</span>':`<span class="educade-hp" role="img" aria-label="${escape(label)}: ${score} percent"><span class="educade-hp-track"><span class="educade-hp-fill ${score<70?'needs-practice':''}" style="width:${score}%"></span></span><strong>${score}%</strong></span>`;
const avatar=(student,portrait)=>`<span class="educade-avatar" aria-hidden="true">${escape(student.name.slice(0,1))}${portrait==='photos'?`<img src="/api/profiles/learners/${encodeURIComponent(student.id)}/image" alt="" loading="lazy">`:''}</span>`;
export function classOverviewHTML(data){
 const {students,lessons,scope,mode,search,sort,portrait,catalogue}=data;
 const withEvidence=students.filter(s=>learnerEvidence(lessons,s.id).length).length;
 return `<div class="educade-summary"><div><span class="educade-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M15 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/></svg></span><strong>${students.length}</strong><span>students</span></div><div><span class="educade-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 20h16M6 16V9m6 7V4m6 12v-5"/></svg></span><strong>${withEvidence}</strong><span>with lesson evidence</span></div><div><span class="educade-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg></span><strong>${students.length-withEvidence}</strong><span>awaiting evidence</span></div></div><section class="assessment-card educade-class-comparison"><div class="educade-class-toolbar"><label>Find a learner<input type="search" data-class-search placeholder="Search students" value="${escape(search)}"></label><label>Sort learners<select data-class-sort><option value="name" ${sort==='name'?'selected':''}>Name A–Z</option><option value="evidence" ${sort==='evidence'?'selected':''}>Least lesson evidence first</option></select></label><label>Portrait style<select data-class-portrait><option value="photos" ${portrait==='photos'?'selected':''}>Photos / avatars</option><option value="initials" ${portrait==='initials'?'selected':''}>Initials</option></select></label></div><div class="educade-learning-tabs" role="tablist" aria-label="Class learning domains">${Object.entries(learningTabs).map(([id,tab])=>`<button type="button" role="tab" data-class-scope="${id}" aria-selected="${scope===id}" tabindex="${scope===id?'0':'-1'}">${tab.name}</button>`).join('')}</div><div class="educade-data-view"><p>Recorded skill practice${mode==='standards'?' · Teacher judgments':''}</p><div class="educade-mode-switch" role="group" aria-label="Class data view">${[['bars','Progress bars'],['heatmap','Class heatmap'],['standards','Standards progress']].map(([id,label])=>`<button type="button" data-class-mode="${id}" aria-pressed="${mode===id}">${label}</button>`).join('')}</div></div><div class="educade-table-scroll" role="region" aria-label="${escape(learningTabs[scope].name)} class comparison" tabindex="0"><table class="educade-class-table"><caption class="sr-only">Learners and recorded ${escape(learningTabs[scope].name)} evidence</caption><thead><tr><th scope="col">Student</th>${classAxes(catalogue,scope).map(axis=>`<th scope="col"><button type="button" data-class-axis="${escape(axis.id)}" aria-expanded="${data.expandedAxis===axis.id}"><strong>${escape(axis.label)}</strong><span>${data.expandedAxis===axis.id?'− Hide evidence':'+ Show evidence'}</span></button></th>`).join('')}</tr></thead><tbody data-class-rows>${classRowsHTML(data)}</tbody></table></div><p class="educade-comparison-note">${mode==='standards'?'Standards levels require a teacher review against the selected criterion.':'Bars and heatmap show accuracy only for responses linked to a skill.'} Unmapped quizzes and lesson feedback remain available in each learner’s evidence.</p></section>`;
}
export function classRowsHTML(data){
 const {students,lessons,catalogue,scope,mode,search,sort,portrait,records=[]}=data,axes=classAxes(catalogue,scope);
 const filtered=students.filter(s=>s.name.toLocaleLowerCase().includes(search.toLocaleLowerCase())).slice().sort((a,b)=>(sort==='evidence'?learnerEvidence(lessons,a.id).length-learnerEvidence(lessons,b.id).length:0)||a.name.localeCompare(b.name));
 return filtered.map(student=>`<tr><th scope="row"><div class="educade-learner">${avatar(student,portrait)}<div><button type="button" data-assessment-learner="${escape(student.id)}" class="educade-profile-link">${escape(student.name)}</button><button type="button" data-assessment-learner="${escape(student.id)}" class="educade-evidence-link">+ Show learning evidence</button><small>${learnerEvidence(lessons,student.id).length} lesson${learnerEvidence(lessons,student.id).length===1?'':'s'} with evidence</small></div></div></th>${axes.map(axis=>{const stats=axisStats(catalogue,records.filter(r=>r.learnerId===student.id),axis);return `<td><button type="button" class="educade-score-cell ${mode==='heatmap'?'educade-heat-cell':''}" data-class-evidence="${escape(axis.id)}" data-class-learner="${escape(student.id)}">${mode==='standards'?'<span class="educade-no-evidence">Not reviewed</span>':mode==='heatmap'?`<span class="educade-heat ${stats.score===null?'empty':stats.score<70?'needs-practice':'has-evidence'}">${stats.score===null?'No evidence yet':stats.score+'%'}</span>`:progressBar(stats.score,axis.label)}</button>${data.expandedAxis===axis.id?`<div class="educade-cell-evidence"><strong>${stats.attempts} linked responses</strong><small>${stats.independent} independent · ${stats.supported} supported</small></div>`:''}</td>`;}).join('')}</tr>`).join('')||`<tr><td colspan="${axes.length+1}"><p class="assessment-empty">${students.length?'No learners match your search.':'Add learners from Classes to begin.'}</p></td></tr>`;
}
export function practiceRadarHTML(axes,scores){
 // Preserve EDUCADE's missing-evidence rule: no missing point is plotted at zero,
 // and no polygon bridges a missing result.
 if(scores.filter(score=>score!==null).length<3)return '<p class="educade-no-evidence">A skill profile will appear after at least three areas have linked evidence.</p>';
 const count=axes.length,cx=250,cy=200,radius=125,point=(i,r)=>[cx+Math.sin(i*2*Math.PI/count)*r,cy-Math.cos(i*2*Math.PI/count)*r];
 const polygon=r=>axes.map((axis,i)=>point(i,r).join(',')).join(' ');
 const area=scores.every(score=>score!==null)?`<polygon class="educade-radar-area" points="${scores.map((score,i)=>point(i,radius*score/100).join(',')).join(' ')}"/>`:scores.map((score,i)=>{const next=(i+1)%count;if(score===null||scores[next]===null)return '';const a=point(i,radius*score/100),b=point(next,radius*scores[next]/100);return `<line class="educade-radar-area" x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}"/>`;}).join('');
 return `<svg class="educade-practice-radar" viewBox="0 0 500 400" role="img" aria-label="Recorded skill practice profile; missing evidence is omitted">${[.25,.5,.75,1].map(n=>`<polygon class="educade-radar-grid" points="${polygon(radius*n)}"/>`).join('')}${area}${axes.map((axis,i)=>{const end=point(i,radius),label=point(i,radius+34),dot=scores[i]===null?null:point(i,radius*scores[i]/100);return `<line class="educade-radar-axis" x1="${cx}" y1="${cy}" x2="${end[0]}" y2="${end[1]}"/><text x="${label[0]}" y="${label[1]}" text-anchor="middle">${escape(axis.label)}</text>${dot?`<circle cx="${dot[0]}" cy="${dot[1]}" r="4"/>`:''}`;}).join('')}</svg>`;
}
